/*
 * HiFi4 4-lane int16 MAC for the resample FIR tap accumulation.
 *
 * Replaces the scalar `un += xn[k] * hn[k]` loop in resample_x64k_12k8() with
 * AE_MULAAAAQ16 4-lane multiply-accumulate.
 *
 * Bit-exactness contract with the scalar reference:
 *  - The scalar reference accumulates `int16 * int16` products into an
 *    `int32_t un`. Each Q15*Q15 product fits in Q30 (< 2^31). With the real
 *    h_16k_12k8_q15 coefficient set the w=20 sum stays within int32 range
 *    (max |sum| ~= 1.87e9 < 2^31), so the reference does not overflow on the
 *    production 16 KHz path. The SIMD path matches the reference's int32
 *    wrapping semantics by narrowing each 4-lane partial to int32 before
 *    accumulating: two's-complement addition is associative mod 2^32, so a
 *    per-group `(int32_t)partial` + int32 accumulation is identical to the
 *    scalar per-element `un += xn[k]*hn[k]` accumulation, including any
 *    hypothetical overflow wrap.
 *  - Only the FIR tap accumulation is vectorized; filter_hp50() biquad and
 *    Q14 output rounding stay scalar in ltpf.c.
 *
 * xn, hn point at the first tap (after the x -= w-1 pre-decrement done by the
 * caller); w is the number of int16 taps (multiple of 4 for p=4/2, handled
 * with a scalar tail for p=8 where w=10).
 */
static inline int32_t xtensa_resample_fir(
    const int16_t *xn, const int16_t *hn, int w)
{
    const ae_int16x4 *pa = (const ae_int16x4 *)xn;
    const ae_int16x4 *pb = (const ae_int16x4 *)hn;
    int32_t un = 0;
    ae_valign align_a = AE_LA64_PP(pa);
    ae_valign align_b = AE_LA64_PP(pb);

    int k = 0;
    for (; k + 4 <= w; k += 4) {
        ae_int16x4 va, vb;
        ae_int64 sum = 0;
        AE_LA16X4_IP(va, align_a, pa);
        AE_LA16X4_IP(vb, align_b, pb);
        AE_MULAAAAQ16(sum, va, vb);
        /* narrow per-group to int32 to match scalar int32 accumulation
         * (associative mod 2^32 keeps this bit-exact with per-element wrap) */
        un += (int32_t)(int64_t)sum;
    }

    for (; k < w; k++)
        un += (int32_t)xn[k] * hn[k];

    return un;
}

#if !defined(TEST_XTENSA_HIFI4)
/*
 * 16 KHz resample dispatches its 20-tap FIR (p=4, w=20) to the HiFi4 SIMD
 * helper. The 64-bit accumulator is narrowed to int32 before the scalar
 * filter_hp50() biquad, matching the scalar resample_x64k_12k8() path.
 *
 * A build may pass -DLC3_RESAMPLE_16K_DISABLE to keep the scalar resample
 * path (used for the B/baseline A/B variant so the only delta versus R is
 * the resample SIMD).
 */
#if !defined(LC3_RESAMPLE_16K_DISABLE)
#define LC3_RESAMPLE_16K_SIMD 1
#endif
#endif
#endif

#endif /* LC3_LTPF_XTENSA_H */

